use lrucache::Lru;

#[test]
fn evicts_oldest_when_full() {
    let mut c = Lru::new(2);
    c.put("a", 1);
    c.put("b", 2);
    c.put("c", 3);
    assert_eq!(c.get("a"), None, "a should have been evicted");
}

#[test]
fn get_refreshes_entry() {
    let mut c = Lru::new(2);
    c.put("a", 1);
    c.put("b", 2);
    c.get("a");
    c.put("c", 3);
    assert_eq!(c.get("a"), Some(&1), "a was touched and must survive");
}

