use std::collections::VecDeque;

pub struct Lru {
    cap: usize,
    order: VecDeque<(&'static str, i32)>,
}

impl Lru {
    pub fn new(cap: usize) -> Self {
        Lru { cap, order: VecDeque::new() }
    }

    pub fn put(&mut self, k: &'static str, v: i32) {
        self.order.retain(|(key, _)| *key != k);
        if self.order.len() == self.cap {
            self.order.pop_front();
        }
        self.order.push_back((k, v));
    }

    pub fn get(&mut self, k: &str) -> Option<&i32> {
        self.order.iter().find(|(key, _)| *key == k).map(|(_, v)| v)
    }
}

